from typing import Annotated

import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer, OAuth2PasswordRequestForm
from pydantic import BaseModel

from security import create_access_token, decode_access_token, hash_password, verify_password

app = FastAPI(title="Auth lab")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")


class User(BaseModel):
    username: str
    full_name: str
    role: str = "member"
    disabled: bool = False


class UserInDB(User):
    hashed_password: str


class Token(BaseModel):
    access_token: str
    token_type: str = "bearer"


# Demo users with hashed passwords. Never store or log the passwords themselves.
USERS = {
    "ana": UserInDB(username="ana", full_name="Ana Lima", role="admin",
                    hashed_password=hash_password("correct horse battery")),
    "bilal": UserInDB(username="bilal", full_name="Bilal Khan",
                      hashed_password=hash_password("staple paper clip")),
    "chen": UserInDB(username="chen", full_name="Chen Wei", disabled=True,
                     hashed_password=hash_password("blue river stone")),
}
DUMMY_HASH = hash_password("a password nobody has")


def authenticate(username: str, password: str) -> UserInDB | None:
    """The user if the password is right, otherwise None. Unknown names take as long as wrong passwords."""
    # TODO 1: look the user up in USERS. If there's no such user, still call verify_password with
    #        DUMMY_HASH (so the answer takes as long) and return None. Otherwise return the user only if
    #        verify_password(password, user.hashed_password) is true.
    return None


@app.post("/token")
def login(form: Annotated[OAuth2PasswordRequestForm, Depends()]) -> Token:
    """The OAuth2 password flow: form fields username and password in, a bearer token out."""
    user = authenticate(form.username, form.password)
    if user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return Token(access_token=create_access_token(user.username, role=user.role))


CREDENTIALS_ERROR = HTTPException(
    status_code=status.HTTP_401_UNAUTHORIZED,
    detail="Could not validate credentials",
    headers={"WWW-Authenticate": "Bearer"},
)


def get_current_user(token: Annotated[str, Depends(oauth2_scheme)]) -> UserInDB:
    # TODO 2: decode the token with decode_access_token; if that raises jwt.InvalidTokenError,
    #        raise CREDENTIALS_ERROR. Then find USERS[claims["sub"]], raising CREDENTIALS_ERROR if it isn't
    #        there, and return the user.
