def require_admin(user: Annotated[UserInDB, Depends(get_active_user)]) -> UserInDB:
    # TODO 3: raise a 403 with the detail "Admins only" unless user.role is "admin"; return the user
    return user


@app.get("/users/me")
def read_me(user: Annotated[UserInDB, Depends(get_active_user)]) -> User:
