"""Password hashing with pwdlib (Argon2) and JSON Web Tokens with PyJWT."""
import os
from datetime import UTC, datetime, timedelta

import jwt
from pwdlib import PasswordHash

# A demo key so the lab runs as it is. Real services read it from the environment (module 5).
SECRET_KEY = os.environ.get("SECRET_KEY", "5a0f3c1e9b7d24c68e1f0a9b3d7c5e2f4a6b8c0d1e3f5a7b9c2d4e6f8a0b1c3d")
ALGORITHM = "HS256"
ACCESS_TOKEN_MINUTES = 15

password_hash = PasswordHash.recommended()


def hash_password(password: str) -> str:
    return password_hash.hash(password)


def verify_password(password: str, hashed: str) -> bool:
    return password_hash.verify(password, hashed)


def create_access_token(subject: str, minutes: int = ACCESS_TOKEN_MINUTES, **claims) -> str:
    """A signed token for subject that expires after the given number of minutes."""
    now = datetime.now(UTC)
    payload = {"sub": subject, "iat": now, "exp": now + timedelta(minutes=minutes), **claims}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def decode_access_token(token: str) -> dict:
    """The token's claims. Raises jwt.InvalidTokenError (ExpiredSignatureError included) if it's not valid."""
    return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])

import jwt
from fastapi.testclient import TestClient

from main import app
from security import ALGORITHM, create_access_token, hash_password, verify_password

client = TestClient(app)


def login(username, password):
    return client.post("/token", data={"username": username, "password": password})


def bearer(token):
    return {"Authorization": f"Bearer {token}"}


def test_hashes_are_salted_and_verifiable():
    first, second = hash_password("s3cret words"), hash_password("s3cret words")
    assert first != second
    assert first.startswith("$argon2id$")
    assert verify_password("s3cret words", first)
    assert not verify_password("wrong", first)


def test_wrong_password_and_unknown_user_get_the_same_answer():
    for username, password in [("ana", "nope"), ("nobody", "nope")]:
        response = login(username, password)
        assert response.status_code == 401
        assert response.json() == {"detail": "Incorrect username or password"}


def test_the_token_opens_users_me_without_the_hash():
    token = login("bilal", "staple paper clip").json()["access_token"]
    response = client.get("/users/me", headers=bearer(token))
    assert response.json() == {"username": "bilal", "full_name": "Bilal Khan", "role": "member",
                               "disabled": False}


def test_missing_expired_and_forged_tokens_are_401():
    assert client.get("/users/me").status_code == 401
    expired = create_access_token("bilal", minutes=-1)
    forged = jwt.encode({"sub": "ana"}, "f" * 64, algorithm=ALGORITHM)
    for token in [expired, forged, "not-a-token"]:
        assert client.get("/users/me", headers=bearer(token)).status_code == 401


def test_disabled_accounts_are_403():
    token = login("chen", "blue river stone").json()["access_token"]
    assert client.get("/users/me", headers=bearer(token)).status_code == 403


