from typing import Annotated

from fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Query
from sqlalchemy import select
from sqlalchemy.orm import Session, sessionmaker

from app import notifications
from app.config import Settings, get_settings
from app.database import SessionDep, get_session_factory
from app.models import Task
from app.schemas import ReportJob, TaskCreate, TaskOut, TaskUpdate
from app.security import CurrentUser

router = APIRouter(prefix="/tasks", tags=["tasks"])


def owned_task(task_id: int, user: CurrentUser, session: SessionDep) -> Task:
    """The caller's task, or 404: someone else's task gets the same answer as a missing one."""
    task = session.get(Task, task_id)
    if task is None or task.owner_id != user.id:
        raise HTTPException(status_code=404, detail="Task not found")
    return task


OwnedTask = Annotated[Task, Depends(owned_task)]


@router.get("")
def list_tasks(
    user: CurrentUser,
    session: SessionDep,
    done: bool | None = None,
    limit: Annotated[int, Query(ge=1, le=100)] = 20,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[TaskOut]:
    query = select(Task).where(Task.owner_id == user.id).order_by(Task.id).limit(limit).offset(offset)
    if done is not None:
        query = query.where(Task.done == done)
    return session.scalars(query).all()


@router.post("", status_code=201)
def create_task(
    data: TaskCreate,
    user: CurrentUser,
    session: SessionDep,
    background: BackgroundTasks,
    settings: Annotated[Settings, Depends(get_settings)],
) -> TaskOut:
    task = Task(**data.model_dump(), owner_id=user.id)
    session.add(task)
    session.commit()
    session.refresh(task)
    # TODO 2: schedule notifications.notify_task_created to run after the response, with
    #        settings.outbox_path, user.username, task.id and task.title
    return task


@router.get("/{task_id}")
def read_task(task: OwnedTask) -> TaskOut:
    return task


@router.patch("/{task_id}")
def update_task(changes: TaskUpdate, task: OwnedTask, session: SessionDep) -> TaskOut:
    for field, value in changes.model_dump(exclude_unset=True).items():
        setattr(task, field, value)
    session.commit()
    session.refresh(task)
    return task


@router.delete("/{task_id}", status_code=204)
def delete_task(task: OwnedTask, session: SessionDep) -> None:
    session.delete(task)
    session.commit()


reports = APIRouter(prefix="/reports", tags=["reports"])


@reports.post("", status_code=202)
def start_report(
    user: CurrentUser,
    background: BackgroundTasks,
    factory: Annotated[sessionmaker[Session], Depends(get_session_factory)],
) -> ReportJob:
    """Start building a summary of your tasks. Poll GET /reports/{job_id} for the result."""
    job_id = notifications.new_job(user.id)
    background.add_task(notifications.build_report, factory, job_id, user.id)
    return ReportJob(job_id=job_id, status="queued")


@reports.get("/{job_id}")
def read_report(job_id: str, user: CurrentUser) -> ReportJob:
    job = notifications.JOBS.get(job_id)
    if job is None or job["owner_id"] != user.id:
        raise HTTPException(status_code=404, detail="Report not found")
    return ReportJob(job_id=job_id, status=job["status"], result=job["result"])

from app.security import create_access_token


def test_register_returns_the_user_without_the_password(client):
    response = client.post("/auth/register", json={"username": "ana", "password": "correct horse battery"})
    assert response.status_code == 201
    assert response.json() == {"id": 1, "username": "ana"}


def test_a_taken_username_is_409(client, make_user):
    make_user("ana")
    response = client.post("/auth/register", json={"username": "ana", "password": "another long one"})
    assert response.status_code == 409


def test_short_passwords_and_bad_usernames_are_422(client):
    assert client.post("/auth/register", json={"username": "ana", "password": "short"}).status_code == 422
    assert client.post("/auth/register", json={"username": "Ana!", "password": "x" * 12}).status_code == 422


def test_login_with_a_wrong_password_is_401(client, make_user):
    make_user("ana")
    response = client.post("/auth/token", data={"username": "ana", "password": "wrong password"})
    assert response.status_code == 401
    assert response.headers["www-authenticate"] == "Bearer"


def test_users_me_needs_a_valid_token(client, make_user):
    headers = make_user("ana")
    assert client.get("/users/me", headers=headers).json()["username"] == "ana"
    assert client.get("/users/me").status_code == 401
    expired = {"Authorization": f"Bearer {create_access_token('ana', minutes=-1)}"}
    assert client.get("/users/me", headers=expired).status_code == 401

